<!doctype html>
<html lang="id">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Berita Acara</title><style>body{background:#f1f5f9;color:#0f172a;font-family:Arial,sans-serif;margin:0;padding:32px}.card{background:#fff;border-radius:18px;box-shadow:0 18px 50px #0f172a16;margin:auto;max-width:720px;padding:28px}.badge{background:{{ $valid ? '#dcfce7' : '#fee2e2' }};border-radius:999px;color:{{ $valid ? '#166534' : '#991b1b' }};display:inline-block;font-size:12px;font-weight:bold;padding:7px 11px}.meta{background:#f8fafc;border-radius:12px;margin-top:20px;padding:16px}.meta p{margin:8px 0}.muted{color:#64748b}</style></head>
<body><main class="card"><span class="badge">{{ $valid ? 'DOKUMEN VALID' : 'BELUM FINAL / TIDAK VALID' }}</span><h1>Verifikasi berita acara</h1><p class="muted">Kode {{ $defense->verification_code }}</p><div class="meta"><p><strong>{{ $defense->project->project_number }}</strong></p><p>{{ $defense->project->student->user->name }} · {{ $defense->project->student->nim }}</p><p>{{ $defense->project->program->name }}</p><p>{{ $defense->project->title }}</p><p>{{ $defense->scheduled_at->format('d M Y H:i') }} · hasil {{ $defense->result ?? '-' }} · nilai {{ $defense->final_score ?? '-' }}</p></div></main></body>
</html>
